#include "cosmos/live_data.hpp"
#include <chrono>
#include <fstream>
#include <unordered_map>
namespace cosmos{static std::int64_t nowMs(){return std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count();}bool loadLiveDataTSV(const std::filesystem::path&file,LiveData&out){std::ifstream in(file);if(!in)return false;std::unordered_map<std::string,std::string>m;std::string line;while(std::getline(in,line)){auto p=line.find('\t');if(p==std::string::npos)continue;m[line.substr(0,p)]=line.substr(p+1);}auto get=[&](const char*k,const std::string&d=""){auto it=m.find(k);return it==m.end()?d:it->second;};auto num=[&](const char*k,double d=0){try{return std::stod(get(k));}catch(...){return d;}};out.apodTitle=get("apod_title",out.apodTitle);out.apodExplanation=get("apod_explanation");out.apodCopyright=get("apod_copyright");out.apodMediaType=get("apod_media_type");out.apodLocalPath=get("apod_local_path");out.apodUrl=get("apod_url");out.neoCount=(int)num("neo_count");out.solarFlareCount=(int)num("solar_flare_count");out.latestQuakeMagnitude=num("quake_mag");out.updatedMs=(std::int64_t)num("updated_ms");out.stale=out.updatedMs==0||nowMs()-out.updatedMs>3600000;return true;}}
